package com.vit.sales.ui;
import com.vit.sales.db.DatabaseManager;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;
public final class PaymentsPanel extends JPanel{private final DatabaseManager db;private final JTable table=new JTable();public PaymentsPanel(DatabaseManager db){this.db=db;setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(16,16,16,16));JButton b=new JButton("Refresh payments");b.addActionListener(e->load());add(b,BorderLayout.NORTH);table.setAutoCreateRowSorter(true);add(new JScrollPane(table),BorderLayout.CENTER);load();}
private void load(){String sql="SELECT p.payment_id,p.order_id,c.customer_name,p.payment_date,p.amount,p.payment_mode,o.order_status FROM Payment p JOIN Orders o ON o.order_id=p.order_id JOIN Customer c ON c.customer_id=o.customer_id ORDER BY p.payment_id DESC";try(Connection c=db.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){DefaultTableModel m=new DefaultTableModel();ResultSetMetaData d=r.getMetaData();for(int i=1;i<=d.getColumnCount();i++)m.addColumn(d.getColumnLabel(i));while(r.next()){Object[] a=new Object[d.getColumnCount()];for(int i=1;i<=a.length;i++)a[i-1]=r.getObject(i);m.addRow(a);}table.setModel(m);}catch(SQLException e){JOptionPane.showMessageDialog(this,e.getMessage(),"Payment query failed",JOptionPane.ERROR_MESSAGE);}}}
